// Post effect CrtPause (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_shift: f32,
  p_tear: f32,
  p_split: f32,
  p_scan: f32,
  p_roll: f32,
  p_rollWidth: f32,
  p_glow: f32,
};
@group(1) @binding(0) var<uniform> material: MaterialParams;
fn material_post(in: PostInput) -> vec3f {
  let v0: f32 = in.screen_uv.y;
  let v1: f32 = (v0 * 260.0);
  let v2: f32 = (in.time * 45.0);
  let v3: f32 = (v1 + v2);
  let v4: f32 = sin(v3);
  let v5: f32 = (v4 * material.p_shift);
  let v6: f32 = (in.time * 31.0);
  let v7: f32 = (v0 * 40.0);
  let v8: f32 = (v6 + v7);
  let v9: f32 = sin(v8);
  let v10: f32 = (v9 * material.p_tear);
  let v11: f32 = (v0 * 9.0);
  let v12: f32 = (in.time * 2.3);
  let v13: f32 = (v11 + v12);
  let v14: f32 = sin(v13);
  let v15: f32 = (v0 * 23.0);
  let v16: f32 = (in.time * 5.1);
  let v17: f32 = (v15 - v16);
  let v18: f32 = sin(v17);
  let v19: f32 = (v14 * v18);
  let v20: f32 = step(0.96, v19);
  let v21: f32 = (v10 * v20);
  let v22: f32 = (v5 + v21);
  let v23: f32 = (in.time / material.p_roll);
  let v24: f32 = fract(v23);
  let v25: f32 = (material.p_rollWidth * 2.0);
  let v26: f32 = (v25 + 1.0);
  let v27: f32 = (v24 * v26);
  let v28: f32 = (v27 - material.p_rollWidth);
  let v29: f32 = (v0 - v28);
  let v30: f32 = abs(v29);
  let v31: f32 = smoothstep(0.0, material.p_rollWidth, v30);
  let v32: f32 = (v31 * -1.0);
  let v33: f32 = (v32 + 1.0);
  let v34: f32 = (v33 * material.p_shift);
  let v35: f32 = (v34 * 2.0);
  let v36: f32 = (v22 + v35);
  let v37: f32 = in.size.y;
  let v38: f32 = (v37 / 1080.0);
  let v39: f32 = (v36 * v38);
  let v40: vec2f = vec2f(v39, 0.0);
  let v41: vec2f = (v40 * in.texel);
  let v42: vec2f = (in.screen_uv + v41);
  let v43: f32 = (material.p_split * v38);
  let v44: f32 = (v33 + 1.0);
  let v45: f32 = (v43 * v44);
  let v46: vec2f = vec2f(v45, 0.0);
  let v47: vec2f = (v46 * in.texel);
  let v48: vec2f = (v42 + v47);
  let v49: vec3f = post_color(v48);
  let v50: f32 = v49.x;
  let v51: vec3f = post_color(v42);
  let v52: f32 = v51.y;
  let v53: vec2f = (v42 - v47);
  let v54: vec3f = post_color(v53);
  let v55: f32 = v54.z;
  let v56: vec3f = vec3f(v50, v52, v55);
  let v57: f32 = (v0 * v37);
  let v58: f32 = (v57 * 1.6);
  let v59: f32 = sin(v58);
  let v60: f32 = (v59 * 0.5);
  let v61: f32 = (v60 + 0.5);
  let v62: f32 = (v61 * material.p_scan);
  let v63: f32 = (v62 * -1.0);
  let v64: f32 = (v63 + 1.0);
  let v65: vec3f = (v56 * v64);
  let v66: f32 = (v33 * material.p_glow);
  let v67: f32 = (v66 + 1.0);
  let v68: f32 = clamp(v67, 1.0, 2.0);
  let v69: vec3f = (v65 * v68);
  return v69;
}
